INSERT INTO `articles` (`id`, `slug`, `title`, `category`, `status`, `sort_priority`, `data`, `created_at`, `updated_at`) VALUES ('art-5', 'พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร', 'พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร', 'ข่าวสารอัพเดท', 'published', 100, '{"id": "art-5", "slug": "พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร", "title": "พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร", "category": "ข่าวสารอัพเดท", "status": "published", "excerpt": "บริษัท ไทย-โกเบ เวลดิ้ง จำกัด ผู้ผลิตลวดเชื่อมโกเบจากประเทศญี่ปุ่น และ บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ตัวแทนจัดจำหน่ายหลักสินค้าโกเบในประเทศไทย ได...", "cover_image": "https://www.udo.co.th/storage/posts/January2020/0wDIkiToBqnQybY5UiBD.JPG", "read_time_minutes": 1, "author": "UDO Technical Team", "tags": ["ตัวแทนจำหน่ายลวดเชื่อมโกเบ", "โกเบ", "ลวดเชื่อมโกเบ"], "recommended_products": [], "meta_title": "สนใจเป็นตัวแทนจำหน่ายลวดเชื่อมโกเบ", "meta_description": "พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบ", "content_blocks": [{"id": "block-1", "headline": "", "subheadline": "", "paragraph": "บริษัท ไทย-โกเบ เวลดิ้ง จำกัด ผู้ผลิตลวดเชื่อมโกเบจากประเทศญี่ปุ่น และ บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ตัวแทนจัดจำหน่ายหลักสินค้าโกเบในประเทศไทย ได้ร่วมกันแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร เพิ่มเติมอีก 3 บริษัท อันได้แก่\n\n1. บริษัท คงสวัสดิ์ อินเตอร์เทรด จำกัด\n\n2. บริษัท ยูนิเวอร์ส ออฟ อีควิปเมนท์แอนด์กู้ดส์ จำกัด", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9091.JPG"}, {"id": "block-2", "headline": "", "subheadline": "", "paragraph": "3. บริษัท สหปลื้ม จำกัด", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9090.JPG"}, {"id": "block-3", "headline": "", "subheadline": "", "paragraph": "ทางบริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ขอแสดงความยินดีกับผู้แทนจำหน่ายลวดเชื่อมโกเบ ทั้ง 3 บริษัทมา ณ ที่นี้ด้วย สุดท้ายที่ขาดไม่ได้ต้องขอขอบคุณ บริษัท ไทย-โกเบ เวลดิ้ง จำกัด ที่เล็งเห็นถึงความสำคัญในการแต่งตั้งผู้แทนจำหน่ายในครั้งนี้ด้วย", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9089.JPG"}, {"id": "block-4", "headline": "", "subheadline": "", "paragraph": "", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9086.JPG"}, {"id": "block-5", "headline": "", "subheadline": "", "paragraph": "", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9088.JPG"}], "featured": true, "created_at": "2020-01-11 00:18:54", "updated_at": "2020-01-11 00:26:12"}', '2020-01-11 00:18:54', '2020-01-11 00:26:12') ON DUPLICATE KEY UPDATE `title`='พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร', `data`='{"id": "art-5", "slug": "พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร", "title": "พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร", "category": "ข่าวสารอัพเดท", "status": "published", "excerpt": "บริษัท ไทย-โกเบ เวลดิ้ง จำกัด ผู้ผลิตลวดเชื่อมโกเบจากประเทศญี่ปุ่น และ บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ตัวแทนจัดจำหน่ายหลักสินค้าโกเบในประเทศไทย ได...", "cover_image": "https://www.udo.co.th/storage/posts/January2020/0wDIkiToBqnQybY5UiBD.JPG", "read_time_minutes": 1, "author": "UDO Technical Team", "tags": ["ตัวแทนจำหน่ายลวดเชื่อมโกเบ", "โกเบ", "ลวดเชื่อมโกเบ"], "recommended_products": [], "meta_title": "สนใจเป็นตัวแทนจำหน่ายลวดเชื่อมโกเบ", "meta_description": "พิธีการแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบ", "content_blocks": [{"id": "block-1", "headline": "", "subheadline": "", "paragraph": "บริษัท ไทย-โกเบ เวลดิ้ง จำกัด ผู้ผลิตลวดเชื่อมโกเบจากประเทศญี่ปุ่น และ บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ตัวแทนจัดจำหน่ายหลักสินค้าโกเบในประเทศไทย ได้ร่วมกันแต่งตั้งผู้แทนจำหน่ายลวดเชื่อมโกเบในเขต กรุงเทพมหานคร เพิ่มเติมอีก 3 บริษัท อันได้แก่\n\n1. บริษัท คงสวัสดิ์ อินเตอร์เทรด จำกัด\n\n2. บริษัท ยูนิเวอร์ส ออฟ อีควิปเมนท์แอนด์กู้ดส์ จำกัด", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9091.JPG"}, {"id": "block-2", "headline": "", "subheadline": "", "paragraph": "3. บริษัท สหปลื้ม จำกัด", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9090.JPG"}, {"id": "block-3", "headline": "", "subheadline": "", "paragraph": "ทางบริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ขอแสดงความยินดีกับผู้แทนจำหน่ายลวดเชื่อมโกเบ ทั้ง 3 บริษัทมา ณ ที่นี้ด้วย สุดท้ายที่ขาดไม่ได้ต้องขอขอบคุณ บริษัท ไทย-โกเบ เวลดิ้ง จำกัด ที่เล็งเห็นถึงความสำคัญในการแต่งตั้งผู้แทนจำหน่ายในครั้งนี้ด้วย", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9089.JPG"}, {"id": "block-4", "headline": "", "subheadline": "", "paragraph": "", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9086.JPG"}, {"id": "block-5", "headline": "", "subheadline": "", "paragraph": "", "image": "https://www.udo.co.th/storage/posts/January2020/IMG_9088.JPG"}], "featured": true, "created_at": "2020-01-11 00:18:54", "updated_at": "2020-01-11 00:26:12"}', `updated_at`='2020-01-11 00:26:12';
INSERT INTO `articles` (`id`, `slug`, `title`, `category`, `status`, `sort_priority`, `data`, `created_at`, `updated_at`) VALUES ('art-1', '4-เรื่องต้องรู้ก่อนทำงานเชื่อม', '4 เรื่องต้องรู้ ก่อนทำงานเชื่อม', 'เทคนิค & สาระงานช่าง', 'published', 100, '{"id": "art-1", "slug": "4-เรื่องต้องรู้ก่อนทำงานเชื่อม", "title": "4 เรื่องต้องรู้ ก่อนทำงานเชื่อม", "category": "เทคนิค & สาระงานช่าง", "status": "published", "excerpt": "งานช่างเชื่อม เป็นงานช่างอีกชนิดหนึ่งที่ต้องอาศัยทักษะเฉพาะทาง", "cover_image": "https://www.udo.co.th/storage/posts/March2019/iGJNx3GPw0XkUUKbiaAx.jpg", "read_time_minutes": 1, "author": "UDO Technical Team", "tags": ["งานช่างเชื่อม", "ลวดเชื่อม", "งานเชื่อมเหล็ก", "งานเชื่อมโลหะ", "อาชีพช่างเชื่อม", "ช่างเชื่อม"], "recommended_products": [], "meta_title": "งานช่างเชื่อม เป็นงานช่างอีกชนิดหนึ่งที่ต้องอาศัยทักษะเฉพาะทาง ช่างเชื่อมจะเชื่อมงานให้สวยให้ดีนอกจากจะเลือกลวดเชื่อมคุณภาพแล้ว ยังต้องสังเกต 4 อย่างนี้ด้วย", "meta_description": "ลวดเชื่อมเหล็ก ผงฟลั๊กซ์ ลวดเกรดพิเศษ ลวดเชื่อมไฟฟ้า ลวดเซาะร่อง ลวดเชื่อม co2  อื่นๆ อีกมากมาย พร้อมส่งทั่วประเทศ", "content_blocks": [{"id": "block-1", "headline": "", "subheadline": "", "paragraph": "งานช่างเชื่อม เป็นงานช่างอีกชนิดหนึ่งที่ต้องอาศัยทักษะเฉพาะทาง ช่างเชื่อมจะเชื่อมงานให้สวยให้ดีนอกจากจะเลือกลวดเชื่อมคุณภาพแล้ว ยังต้องสังเกต 4 อย่างนี้ด้วย", "image": "https://www.udo.co.th/storage/posts/March2019/4 เรื่องต้องรู้-01.jpg"}, {"id": "block-2", "headline": "", "subheadline": "", "paragraph": "1. ประเมินชิ้นงานเป็นขั้นแรก เลือกคุณสมบัติของลวดเชื่อมให้สอดคล้องกับการใช้งานและความคงทนของงาน", "image": "https://www.udo.co.th/storage/posts/March2019/54434783_2229223073801431_1899776305465917440_n1.jpg"}, {"id": "block-3", "headline": "", "subheadline": "", "paragraph": "2. ความแข็งแรงและชนิดของชิ้นงาน ต้องประเมินโลหะชิ้นงานก่อนเชื่อมว่ามีความแข็งแรงและเป็นโลหะชนิดใดจะทำให้ชิ้นงานสามารถประสานเป็นเนื้อเดียวกันได้สวยงาม คงทน", "image": "https://www.udo.co.th/storage/posts/March2019/54517414_2229223247134747_5090416237314310144_n.jpg"}, {"id": "block-4", "headline": "", "subheadline": "", "paragraph": "3. ตรวจสอบท่าเชื่อม ช่างเชื่อมต้ องตรวจสอบว่าจำเป็นต้องเชื่อมในท่าใดและลวดแต่ละชนิดสามารถเชื่อมได้ในลักษณะใดบ้าง", "image": "https://www.udo.co.th/storage/posts/March2019/53814301_2229223430468062_3641107809933721600_n.jpg"}, {"id": "block-5", "headline": "", "subheadline": "", "paragraph": "4. กระแสไฟฟ้าก็สำคัญ “ดูกระแสไฟฟ้า” ที่เหมาะสมในการใช้งานกับลวดเชื่อมแบบนั้นๆ ซึ่งสามารถดูข้อมูลได้ที่ข้างกล่องลวดเชื่อม\n\nrn UDO พร้อมส่งต่อความรู้และประสบการณ์เพราะเราคือผู้เชี่ยวชาญในอุตสาหกรรม\n\nrn\n\n? ที่ UDO ช่างโลหะสามารถหา ลวดเชื่อม ได้ทุกประเภทรวมถึง อุปกรณ์ตัดเชื่อม ถึงอะไหล่ มาครบจบในที่เดียว\n\nrn ✅ UDO ตัวจริงในอุปกรณ์งานเชื่อมตัดกว่า 40 ปี เราเป็นตัวแทนจำหน่ายสินค้าอย่างเป็นทางการหลากหลายแบรนด์ชั้นนำ ทั้ง KOBELCO, YAWATA, HYUNDAI, POWERWELD, CHAMP, INDALCO, HILCO, WELDSTAR, GOLD, KENZO และอีกมากมาย\n\nrn ? ติดต่อได้ที่ : 0-2212-4651\n\n?  Hotline : 062-815-9999\n\nLine@ :  https://line.me/R/ti/p/%40udowelding\n\nคลิก เว็บไซต์  ?   www.udo.co.th\n\nrn", "image": "https://www.udo.co.th/storage/posts/March2019/54228823_2229223583801380_6527012652420431872_n.jpg"}], "featured": true, "created_at": "2018-04-30 08:56:08", "updated_at": "2019-03-29 11:37:52"}', '2018-04-30 08:56:08', '2019-03-29 11:37:52') ON DUPLICATE KEY UPDATE `title`='4 เรื่องต้องรู้ ก่อนทำงานเชื่อม', `data`='{"id": "art-1", "slug": "4-เรื่องต้องรู้ก่อนทำงานเชื่อม", "title": "4 เรื่องต้องรู้ ก่อนทำงานเชื่อม", "category": "เทคนิค & สาระงานช่าง", "status": "published", "excerpt": "งานช่างเชื่อม เป็นงานช่างอีกชนิดหนึ่งที่ต้องอาศัยทักษะเฉพาะทาง", "cover_image": "https://www.udo.co.th/storage/posts/March2019/iGJNx3GPw0XkUUKbiaAx.jpg", "read_time_minutes": 1, "author": "UDO Technical Team", "tags": ["งานช่างเชื่อม", "ลวดเชื่อม", "งานเชื่อมเหล็ก", "งานเชื่อมโลหะ", "อาชีพช่างเชื่อม", "ช่างเชื่อม"], "recommended_products": [], "meta_title": "งานช่างเชื่อม เป็นงานช่างอีกชนิดหนึ่งที่ต้องอาศัยทักษะเฉพาะทาง ช่างเชื่อมจะเชื่อมงานให้สวยให้ดีนอกจากจะเลือกลวดเชื่อมคุณภาพแล้ว ยังต้องสังเกต 4 อย่างนี้ด้วย", "meta_description": "ลวดเชื่อมเหล็ก ผงฟลั๊กซ์ ลวดเกรดพิเศษ ลวดเชื่อมไฟฟ้า ลวดเซาะร่อง ลวดเชื่อม co2  อื่นๆ อีกมากมาย พร้อมส่งทั่วประเทศ", "content_blocks": [{"id": "block-1", "headline": "", "subheadline": "", "paragraph": "งานช่างเชื่อม เป็นงานช่างอีกชนิดหนึ่งที่ต้องอาศัยทักษะเฉพาะทาง ช่างเชื่อมจะเชื่อมงานให้สวยให้ดีนอกจากจะเลือกลวดเชื่อมคุณภาพแล้ว ยังต้องสังเกต 4 อย่างนี้ด้วย", "image": "https://www.udo.co.th/storage/posts/March2019/4 เรื่องต้องรู้-01.jpg"}, {"id": "block-2", "headline": "", "subheadline": "", "paragraph": "1. ประเมินชิ้นงานเป็นขั้นแรก เลือกคุณสมบัติของลวดเชื่อมให้สอดคล้องกับการใช้งานและความคงทนของงาน", "image": "https://www.udo.co.th/storage/posts/March2019/54434783_2229223073801431_1899776305465917440_n1.jpg"}, {"id": "block-3", "headline": "", "subheadline": "", "paragraph": "2. ความแข็งแรงและชนิดของชิ้นงาน ต้องประเมินโลหะชิ้นงานก่อนเชื่อมว่ามีความแข็งแรงและเป็นโลหะชนิดใดจะทำให้ชิ้นงานสามารถประสานเป็นเนื้อเดียวกันได้สวยงาม คงทน", "image": "https://www.udo.co.th/storage/posts/March2019/54517414_2229223247134747_5090416237314310144_n.jpg"}, {"id": "block-4", "headline": "", "subheadline": "", "paragraph": "3. ตรวจสอบท่าเชื่อม ช่างเชื่อมต้ องตรวจสอบว่าจำเป็นต้องเชื่อมในท่าใดและลวดแต่ละชนิดสามารถเชื่อมได้ในลักษณะใดบ้าง", "image": "https://www.udo.co.th/storage/posts/March2019/53814301_2229223430468062_3641107809933721600_n.jpg"}, {"id": "block-5", "headline": "", "subheadline": "", "paragraph": "4. กระแสไฟฟ้าก็สำคัญ “ดูกระแสไฟฟ้า” ที่เหมาะสมในการใช้งานกับลวดเชื่อมแบบนั้นๆ ซึ่งสามารถดูข้อมูลได้ที่ข้างกล่องลวดเชื่อม\n\nrn UDO พร้อมส่งต่อความรู้และประสบการณ์เพราะเราคือผู้เชี่ยวชาญในอุตสาหกรรม\n\nrn\n\n? ที่ UDO ช่างโลหะสามารถหา ลวดเชื่อม ได้ทุกประเภทรวมถึง อุปกรณ์ตัดเชื่อม ถึงอะไหล่ มาครบจบในที่เดียว\n\nrn ✅ UDO ตัวจริงในอุปกรณ์งานเชื่อมตัดกว่า 40 ปี เราเป็นตัวแทนจำหน่ายสินค้าอย่างเป็นทางการหลากหลายแบรนด์ชั้นนำ ทั้ง KOBELCO, YAWATA, HYUNDAI, POWERWELD, CHAMP, INDALCO, HILCO, WELDSTAR, GOLD, KENZO และอีกมากมาย\n\nrn ? ติดต่อได้ที่ : 0-2212-4651\n\n?  Hotline : 062-815-9999\n\nLine@ :  https://line.me/R/ti/p/%40udowelding\n\nคลิก เว็บไซต์  ?   www.udo.co.th\n\nrn", "image": "https://www.udo.co.th/storage/posts/March2019/54228823_2229223583801380_6527012652420431872_n.jpg"}], "featured": true, "created_at": "2018-04-30 08:56:08", "updated_at": "2019-03-29 11:37:52"}', `updated_at`='2019-03-29 11:37:52';
INSERT INTO `articles` (`id`, `slug`, `title`, `category`, `status`, `sort_priority`, `data`, `created_at`, `updated_at`) VALUES ('art-2', 'ชนิดของลวดเชื่อม', 'ชนิดของลวดเชื่อม', 'เทคนิค & สาระงานช่าง', 'published', 100, '{"id": "art-2", "slug": "ชนิดของลวดเชื่อม", "title": "ชนิดของลวดเชื่อม", "category": "เทคนิค & สาระงานช่าง", "status": "published", "excerpt": "ลวดเชื่อมดีๆ มีมาตรฐาน udo จำหน่ายลวดเชื่อมนานาชนิด ลวดเชื่อมเกรดพิเศษ ลวดเชื่อมหายาก เหมาะกับงาน เเต่ละประเภท", "cover_image": "https://www.udo.co.th/storage/posts/March2019/nk4i5dv3ZY2vNXRGGbcA.jpg", "read_time_minutes": 1, "author": "UDO Technical Team", "tags": ["ชนิดลวดเชื่อม", "ลวดเชื่อมไส้ฟลักซ์", "ลวดเชื่อมมิก", "ลวดเชื่อมทิก"], "recommended_products": [], "meta_title": "ลวดเชื่อม เป็นวัสดุสำคัญในงานเชื่อมโลหะเพื่อให้ชิ้นงานโลหะผสานเข้าด้วยกันเป็นชิ้นเดียว  ซึ่งลวดเชื่อมก็มีหลายชนิด แตกต่างกันที่การใช้งาน ความคงทน", "meta_description": "ลวดเชื่อมดีๆ มีมาตรฐาน udo จำหน่ายลวดเชื่อมนานาชนิด ลวดเชื่อมเกรดพิเศษ ลวดเชื่อมหายาก เหมาะกับงาน เเต่ละประเภท", "content_blocks": [{"id": "block-1", "headline": "", "subheadline": "", "paragraph": "ลวดเชื่อม  เป็นวัสดุสำคัญในงานเชื่อมโลหะเพื่อให้ชิ้นงานโลหะผสานเข้าด้วยกันเป็นชิ้นเดียว  ซึ่งลวดเชื่อมก็มีหลายชนิด แตกต่างกันที่การใช้งาน ความคงทน  วัสดุของลวดเชื่อม   ในงานเชื่อมแบ่งลวดเชื่อมออกเป็น 6 ชนิด ใหญ่ๆ คือ", "image": "https://www.udo.co.th/storage/posts/March2019/-02-021.jpg"}, {"id": "block-2", "headline": "1. ลวดเชื่อมธูปหรือลวดเชื่อมธูปไฟฟ้า ( Welding Electrode)", "subheadline": "", "paragraph": "เป็นลวดเชื่อมที่นิยมใช้งานกันมาก ด้านนอกมีสารเคลือบ( Flux) แกนกลางเป็นลวดโลหะให้ช่างเลือกตามโลหะชิ้นงานที่ต้องการเชื่อม  เช่น ลวดเชื่อมเหล็กและลวดเชื่อมสแตนเลส  อุปกรณ์และเส้นลวดเชื่อมมีราคาไม่สูงนักและมีให้เลือกหลายขนาด", "image": "https://www.udo.co.th/storage/posts/March2019/-03.jpg"}, {"id": "block-3", "headline": "2. ลวดเชื่อมไส้ฟลักซ์ ( Flux Cored Wire)", "subheadline": "", "paragraph": "เป็นลวดเชื่อมโลหะแบบเป็นม้วนลวดโลหะมีแกนกลวงบรรจุด้วยสารเคลือบ Flux อยู่ภายในลวด มีราคาค่อนข้างสูง แต่มีประสิทธิภาพสูง เชื่อมได้รวดเร็วและสวยงาม", "image": "https://www.udo.co.th/storage/posts/March2019/-04.jpg"}, {"id": "block-4", "headline": "3. ลวดเชื่อมมิก หรือลวดเชื่อม CO2 (Mig welding wire)", "subheadline": "", "paragraph": "เป็นลวดเชื่อมม้วน  ลวดโลหะเปลือยไม่มีสารเคลือบหุ้มภายนอก  มีจุดเด่นที่เชื่อมงานได้เร็วและมีต้นทุนค่าลวดค่อนข้างต่ำ", "image": "https://www.udo.co.th/storage/posts/March2019/-05.jpg"}, {"id": "block-5", "headline": "4. ลวดเชื่อมทิกหรือลวดเชื่อมอาร์กอน ( Tig welding rod )", "subheadline": "", "paragraph": "เป็นลวดเชื่อมเปลือย เป็นเส้นยาวเส้นละประมาณ 1 เมตร  นิยมใช้กับงานเชื่อมที่มีความละเอียด สามารถเลือกวัสดุ ลวดเชื่อมเหล็ก อลูมิเนียม สแตนเลส ทองเหลือง และโลหะอื่นๆ", "image": "https://www.udo.co.th/storage/posts/March2019/-06.jpg"}, {"id": "block-6", "headline": "5. ลวดเชื่อมเซาะร่องหรือลวดเชื่อมเกาจ์ ( Gouging Electrode)", "subheadline": "", "paragraph": "เป็นลวดเชื่อมใช้ทำความสะอาดแนวเชื่อมเพื่อเตรียมชิ้นงาน และกำจัดเนื้อโลหะส่วนเกินที่เชื่อมไม่ได้คุณภาพออกจากชิ้นงาน ให้งานเชื่อมสวยงาม  เหมาะสำหรับการเซาะร่อง เจาะรู หรือ ใช้ในงานตัด", "image": "https://www.udo.co.th/storage/posts/March2019/-07.jpg"}, {"id": "block-7", "headline": "6. ลวดเชื่อมพิเศษ", "subheadline": "", "paragraph": "เป็นกลุ่มชนิดของลวดเชื่อมที่ออกแบบมาเพื่อใช้เฉาะงาน เช่น ลวดเชื่อมพอกผิวแข็ง ลวดเชื่อมอินโคเนล ลวดเชื่อมไฟฟ้าอลูมิเนียม ลวดเชื่อมนิกเกิ้ลอัลลอยด์ ลวดเชื่อมไฟฟ้าทองแดง เป็นต้น\n\nช่างเชื่อมต้องการ ลวดเชื่อม และอุปกรณ์เชื่อมอะไร UDO พร้อมให้คำแนะนำ คำปรึกษา เลือกสินค้าคุณภาพให้กับช่างเชื่อมทุกคน เรื่องงานเชื่อมอย่าลืมนึกถึง UDO", "image": ""}], "featured": false, "created_at": "2018-04-30 08:56:08", "updated_at": "2025-06-21 15:09:32"}', '2018-04-30 08:56:08', '2025-06-21 15:09:32') ON DUPLICATE KEY UPDATE `title`='ชนิดของลวดเชื่อม', `data`='{"id": "art-2", "slug": "ชนิดของลวดเชื่อม", "title": "ชนิดของลวดเชื่อม", "category": "เทคนิค & สาระงานช่าง", "status": "published", "excerpt": "ลวดเชื่อมดีๆ มีมาตรฐาน udo จำหน่ายลวดเชื่อมนานาชนิด 